const cookie=n=>decodeURIComponent(document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(n+'='))?.split('=').slice(1).join('=')||'');
async function api(path,o={}){const m=(o.method||'GET').toUpperCase(),h={'content-type':'application/json',...(o.headers||{})};if(!['GET','HEAD'].includes(m)&&cookie('antiqua_csrf'))h['x-csrf-token']=cookie('antiqua_csrf');const r=await fetch(path,{...o,headers:h,credentials:'same-origin'});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||'Request failed');e.status=r.status;e.data=d;throw e}return d}
function toast(text){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
const statusPairs={ACTIVE:['Активно','Active'],LIVE:['Идут торги','Live'],CLOSED:['Завершено','Closed'],SCHEDULED:['Запланировано','Scheduled'],PENDING:['Ожидает ответа','Pending'],COUNTERED_BY_SELLER:['Встречное предложение продавца','Seller countered'],COUNTERED_BY_BUYER:['Встречное предложение покупателя','Buyer countered'],ACCEPTED:['Принято','Accepted'],DECLINED:['Отклонено','Declined'],AWAITING_PAYMENT_CONNECTOR:['Ожидает оплаты','Awaiting payment'],CANCELLED:['Отменено','Cancelled'],DRAFT:['Черновик','Draft'],CATALOGUE_REVIEW:['Каталожная проверка','Catalogue review'],CHANGES_REQUESTED:['Нужны изменения','Changes requested'],APPROVED:['Одобрено','Approved'],PUBLISHED:['Опубликовано','Published'],DISABLED:['Отключена','Disabled'],ENABLED:['Включена','Enabled'],PRIVATE:['Приватно','Private'],PUBLIC:['Публично','Public'],UNLISTED:['По ссылке','Unlisted'],PERSONAL:['Личная','Personal'],CURATED:['Кураторская','Curated'],DISTRIBUTED:['Распределённая','Distributed'],INSTITUTIONAL:['Институциональная','Institutional'],VERIFIED:['Подтверждено','Verified'],CANDIDATE:['Кандидат','Candidate'],KNOWN_PRIVATE:['Известно, приватно','Known private'],MISSING:['Не найдено','Missing'],UNKNOWN_LOCATION:['Местонахождение неизвестно','Unknown location'],USER_SUPPLIED:['Предоставлено владельцем','User supplied'],PLATFORM_RECORD:['Запись платформы','Platform record'],REVIEWED:['Проверено','Reviewed'],NO_FLAG:['Ограничений не отмечено','No flag'],REVIEW_REQUIRED:['Требуется проверка','Review required'],NOT_SCREENED:['Не проверено','Not screened'],NOT_STARTED:['Не начато','Not started'],NOT_CONFIGURED:['Не настроено','Not configured'],QUOTE_REQUIRED:['Нужен расчёт','Quote required'],QUOTE_READY:['Расчёт готов','Quote ready']};
function status(v){const p=statusPairs[String(v||'')];return p?(state.lang==='ru'?p[0]:p[1]):String(v||'—').replaceAll('_',' ')}
function relative(d){if(!d)return'';const mins=Math.max(0,Math.round((Date.now()-Date.parse(d))/60000));if(mins<2)return state.lang==='ru'?'только что':'just now';if(mins<60)return state.lang==='ru'?`${mins} мин назад`:`${mins}m ago`;const h=Math.round(mins/60);if(h<24)return state.lang==='ru'?`${h} ч назад`:`${h}h ago`;const days=Math.round(h/24);return state.lang==='ru'?`${days} дн назад`:`${days}d ago`}
function persistCompare(){localStorage.setItem('antiqua_compare',JSON.stringify(state.compare))}
function syncShell(){document.documentElement.lang=state.lang;document.title=`ANTIQUA — ${t('shop')}`;const labels={shop:t('shop'),auctions:t('auctions'),collections:t('collections'),exhibitions:t('exhibitions'),dealers:t('dealers'),account:t('account'),trust:t('trust')};$$('[data-nav]').forEach(a=>{const k=a.dataset.nav;if(labels[k])a.querySelector('span')?a.querySelector('span').textContent=labels[k]:a.textContent=labels[k]});$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.lang));const footer=$('#footerCopy');if(footer)footer.textContent=state.lang==='ru'?'Собирать · Исследовать · Объединять · Показывать · Приобретать · Сохранять':'Collect · Research · Reunite · Exhibit · Acquire · Preserve';const skip=$('.skip-link');if(skip)skip.textContent=state.lang==='ru'?'К содержанию':'Skip to content';const persona=$('#persona');if(persona)persona.textContent=state.me?.account?.roles?.includes('ADMIN')?(state.lang==='ru'?'Оператор':'Operator'):state.me?.account?.roles?.includes('SELLER')?t('sellerRole'):t('buyer');const trust=$('#trustNav');if(trust)trust.hidden=!state.me?.account?.roles?.some(r=>['CATALOGUER','TRUST_REVIEWER','ADMIN'].includes(r));syncNavigation()}
function syncNavigation(){const root=(location.hash.slice(1).split('/')[0]||'shop');$$('[data-nav]').forEach(a=>a.toggleAttribute('aria-current',a.dataset.nav===root))}
async function refresh(){const [catalog,health,collections,ensembles,exhibitions,me]=await Promise.all([api('/api/catalog'),api('/api/health'),api('/api/collections'),api('/api/ensembles'),api('/api/exhibitions'),api('/api/auth/me')]);state.catalog=catalog;state.health=health;state.collections=collections.collections||[];state.ensembles=ensembles.ensembles||[];state.exhibitions=exhibitions.exhibitions||[];state.me=me;if(!state.me.account&&health.preview){await api('/api/auth/demo-login',{method:'POST',body:JSON.stringify({persona:state.persona})});state.me=await api('/api/auth/me')}state.client=state.me.account?await api('/api/client-state'):null;syncShell()}
function sellerBy(id){return state.catalog.sellers.find(x=>x.id===id)}
function lotContext(id){
 const exhibition=state.exhibitions.find(e=>(e.sections||[]).some(s=>(s.items||[]).some(i=>i.objectId===id||i.object?.id===id)))||null;
 const collection=state.collections.find(c=>(c.items||[]).some(i=>i.objectId===id||i.object?.id===id))||null;
 return{exhibition,collection}
}
function entryForLot(o){
 const li=state.catalog.listings.find(x=>x.lotId===o.id),au=state.catalog.auctions.find(x=>x.lotId===o.id),context=lotContext(o.id),auctionOpen=Boolean(au&&au.state!=='CLOSED');
 const purpose=auctionOpen?'AUCTION':li?'BUY':context.exhibition||context.collection?'EXHIBIT':'HISTORY';
 return{lot:o,listing:li||null,auction:au||null,seller:li?.seller||sellerBy(li?.sellerId),method:auctionOpen?'AUCTION':li?.saleType||'NOT_FOR_SALE',purpose,context,price:li?.price??(auctionOpen?au?.currentBid:null),currency:li?.currency??au?.currency??o.currency??'EUR'}
}
function discovery(){return state.catalog.lots.map(entryForLot)}
function filteredEntries(){
 let xs=discovery(),f=state.filters,q=f.q.trim().toLowerCase();
 if(f.purpose&&f.purpose!=='ALL')xs=xs.filter(x=>x.purpose===f.purpose);
 if(q)xs=xs.filter(x=>[l(x.lot.title),l(x.lot.maker),l(x.lot.period),l(x.lot.department),l(x.lot.materials),l(x.lot.technique),l(x.lot.origin),x.seller?.name].join(' ').toLowerCase().includes(q));
 if(f.category!=='ALL')xs=xs.filter(x=>x.lot.department?.en===f.category);if(f.era!=='ALL')xs=xs.filter(x=>x.lot.period?.en===f.era);if(f.country!=='ALL')xs=xs.filter(x=>x.lot.origin?.en===f.country);if(f.material!=='ALL')xs=xs.filter(x=>String(x.lot.materials?.en||'').split(',').map(v=>v.trim()).includes(f.material));if(f.technique!=='ALL')xs=xs.filter(x=>x.lot.technique?.en===f.technique);if(f.condition!=='ALL')xs=xs.filter(x=>x.lot.conditionGrade===f.condition);if(f.location!=='ALL')xs=xs.filter(x=>x.lot.locationLabel?.en===f.location);if(f.purchaseMethod!=='ALL')xs=xs.filter(x=>x.lot.purchaseMethods?.includes(f.purchaseMethod));if(f.seller!=='ALL')xs=xs.filter(x=>x.listing?.sellerId===f.seller);
 if(f.priceMin!=='')xs=xs.filter(x=>x.price!=null&&Number(x.price)>=Number(f.priceMin));if(f.priceMax!=='')xs=xs.filter(x=>x.price!=null&&Number(x.price)<=Number(f.priceMax));
 const price=x=>x.price==null?Number.POSITIVE_INFINITY:Number(x.price);if(f.sort==='PRICE_ASC')xs.sort((a,b)=>price(a)-price(b));if(f.sort==='PRICE_DESC')xs.sort((a,b)=>price(b)-price(a));if(f.sort==='ENDING')xs.sort((a,b)=>Date.parse(a.auction?.endsAt||'2999-01-01')-Date.parse(b.auction?.endsAt||'2999-01-01'));return xs
}
function methodLabel(m){return m==='BUY_NOW'?t('buyNow'):m==='MAKE_OFFER'?t('makeOffer'):m==='AUCTION'?t('auction'):m==='PRIVATE_SALE'?t('privateSale'):t('notForSale')}
function purposeLabel(p){const ru={ALL:'Все предметы',BUY:'Купить',AUCTION:'Аукцион',EXHIBIT:'Музей / экспонаты',HISTORY:'История'},en={ALL:'All objects',BUY:'Buy',AUCTION:'Auction',EXHIBIT:'Museum / exhibits',HISTORY:'History'};return(state.lang==='ru'?ru:en)[p]||p}
function countdownText(endsAt){
 const ms=Date.parse(endsAt||'')-Date.now();if(!Number.isFinite(ms)||ms<=0)return state.lang==='ru'?'Завершён':'Ended';
 const total=Math.floor(ms/1000),days=Math.floor(total/86400),hours=Math.floor(total%86400/3600),mins=Math.floor(total%3600/60),secs=total%60;
 if(days>0)return state.lang==='ru'?days+' д '+hours+' ч':days+'d '+hours+'h';
 return [hours,mins,secs].map(x=>String(x).padStart(2,'0')).join(':')
}
function updateAuctionTimers(){$$('[data-auction-timer]').forEach(el=>{el.textContent=countdownText(el.dataset.endsAt)})}
function purposeBar(){
 const counts=Object.fromEntries(['BUY','AUCTION','EXHIBIT','HISTORY'].map(k=>[k,discovery().filter(x=>x.purpose===k).length]));
 return`<div class="purpose-bar" role="tablist" aria-label="${state.lang==='ru'?'Режим каталога':'Catalogue mode'}">${['ALL','BUY','AUCTION','EXHIBIT','HISTORY'].map(k=>`<button type="button" class="${state.filters.purpose===k?'active':''}" data-purpose-filter="${k}"><span>${purposeLabel(k)}</span><b>${k==='ALL'?discovery().length:counts[k]}</b></button>`).join('')}</div>`
}
function isSaved(id){return state.client?.savedLots?.includes(id)}
function isWatched(id){return state.client?.watchAlerts?.includes(id)}
function isCompared(id){return state.compare.includes(id)}
function card(entry){
 const o=entry.lot,s=entry.seller,auction=entry.auction,shop=entry.listing,purpose=entry.purpose||(auction&&auction.state!=='CLOSED'?'AUCTION':shop?'BUY':'HISTORY'),nextBid=auction?Number(auction.currentBid)+Number(auction.increment):null,isBuyer=state.me.account?.roles?.includes('BUYER');
 let commercial='',action='';
 if(purpose==='AUCTION'&&auction){
  commercial=`<div class="auction-card-price"><div><span>${state.lang==='ru'?'Текущая ставка':'Current bid'}</span><strong>${money(auction.currentBid,auction.currency)}</strong></div><small>${state.lang==='ru'?'Следующая':'Next'}: <b>${money(nextBid,auction.currency)}</b> · ${state.lang==='ru'?'шаг':'step'} ${money(auction.increment,auction.currency)}</small><small class="auction-countdown">⏱ <span data-auction-timer data-ends-at="${esc(auction.endsAt)}">${countdownText(auction.endsAt)}</span></small></div>`;
  action=isBuyer?`<button class="primary-button" data-bid="${esc(auction.id)}" data-min="${nextBid}">${state.lang==='ru'?'Ставка от ':'Bid from '}${money(nextBid,auction.currency)}</button>`:`<button class="secondary-button" data-passport="${esc(o.id)}">${t('open')}</button>`
 }else if(purpose==='BUY'&&shop){
  commercial=`<div class="object-price">${money(shop.price,shop.currency)}</div><small class="commercial-hint">${methodLabel(shop.saleType)}</small>`;
  action=isBuyer?(shop.saleType==='MAKE_OFFER'?`<button class="secondary-button" data-offer="${esc(shop.id)}" data-price="${shop.price}" data-currency="${shop.currency}">${t('offer')}</button>`:`<button class="primary-button" data-buy="${esc(shop.id)}">${t('buy')}</button>`):`<button class="secondary-button" data-passport="${esc(o.id)}">${t('open')}</button>`
 }else if(purpose==='EXHIBIT'){
  const target=entry.context.exhibition?`#exhibition/${esc(entry.context.exhibition.id)}`:entry.context.collection?`#collection/${esc(entry.context.collection.id)}`:'#shop';
  commercial=`<div class="purpose-copy"><strong>${purposeLabel('EXHIBIT')}</strong><small>${esc(l(entry.context.exhibition?.title||entry.context.collection?.title)||t('objectHistory'))}</small></div>`;
  action=`<a class="secondary-button" href="${target}">${state.lang==='ru'?'Открыть экспозицию':'Open display'}</a>`
 }else{
  commercial=`<div class="purpose-copy"><strong>${purposeLabel('HISTORY')}</strong><small>${state.lang==='ru'?'Паспорт, provenance и история изменений':'Passport, provenance and revision history'}</small></div>`;
  action=`<button class="secondary-button" data-passport="${esc(o.id)}">${state.lang==='ru'?'Смотреть историю':'View history'}</button>`
 }
 return`<article class="object-card v12-card market-card-v16" data-direct-card data-open-passport="${esc(o.id)}" ${auction?`data-auction-id="${esc(auction.id)}"`:''} tabindex="0" role="button" aria-label="${esc(l(o.title))}"><div class="card-media-wrap"><div class="object-image"><img loading="lazy" decoding="async" src="${esc(o.image)}" alt="${esc(l(o.title))}"></div><div class="card-chrome"><button class="round-action ${isSaved(o.id)?'active':''}" data-save="${esc(o.id)}" aria-label="${t('save')}">♡</button><button class="round-action ${isCompared(o.id)?'active':''}" data-compare="${esc(o.id)}" aria-label="${t('compare')}">⇄</button></div><span class="commerce-tag">${purposeLabel(purpose)}</span></div><div class="object-copy v12-card-copy"><div class="micro">${esc(l(o.department))} · ${esc(o.objectId)}</div><h3>${esc(l(o.title))}</h3><div class="muted">${esc(l(o.maker))} · ${esc(l(o.period))}</div><div class="card-commercial">${commercial}</div><div class="seller-mini">${s?`${esc(s.name)}${s.verified?' · ✓':''}`:purpose==='AUCTION'?`${t('auction')} · ${esc(l(state.catalog.sale.title))}`:''}</div><div class="card-row v12-card-actions"><button class="quiet-button" data-passport="${esc(o.id)}">${t('passport')}</button>${action}</div></div></article>`
}
function optionHtml(list,current,allLabel){return`<option value="ALL">${esc(allLabel)}</option>${(list||[]).map(x=>`<option value="${esc(x.value)}" ${x.value===current?'selected':''}>${esc(l(x.label))}</option>`).join('')}`}
function activeFilterCount(){return Object.entries(state.filters).filter(([k,v])=>!['q','sort','purpose'].includes(k)&&v!==''&&v!=='ALL').length+(state.filters.purpose!=='ALL'?1:0)}
function facetPanel(){const f=state.catalog.facets,F=state.filters;return`<aside class="facet-panel"><div class="facet-head"><strong>${t('filters')}</strong><button class="text-button" data-reset-filters>${t('reset')}</button></div><label>${t('category')}<select data-filter="category">${optionHtml(f.categories,F.category,t('all'))}</select></label><label>${t('era')}<select data-filter="era">${optionHtml(f.eras,F.era,t('all'))}</select></label><label>${t('country')}<select data-filter="country">${optionHtml(f.countries,F.country,t('all'))}</select></label><label>${t('material')}<select data-filter="material">${optionHtml(f.materials,F.material,t('all'))}</select></label><label>${t('technique')}<select data-filter="technique">${optionHtml(f.techniques,F.technique,t('all'))}</select></label><label>${t('condition')}<select data-filter="condition">${optionHtml(f.conditions,F.condition,t('all'))}</select></label><label>${t('location')}<select data-filter="location">${optionHtml(f.locations,F.location,t('all'))}</select></label><label>${t('purchase')}<select data-filter="purchaseMethod">${optionHtml(f.purchaseMethods,F.purchaseMethod,t('all'))}</select></label><label>${t('seller')}<select data-filter="seller">${optionHtml(f.sellers,F.seller,t('all'))}</select></label><div class="price-filter"><span>${t('price')}</span><div><input data-filter="priceMin" inputmode="numeric" type="number" min="0" placeholder="${f.price.min}" value="${esc(F.priceMin)}"><span>—</span><input data-filter="priceMax" inputmode="numeric" type="number" min="0" placeholder="${f.price.max}" value="${esc(F.priceMax)}"></div></div></aside>`}
function filterChips(){const f=state.filters,meta={category:t('category'),era:t('era'),country:t('country'),material:t('material'),technique:t('technique'),condition:t('condition'),location:t('location'),purchaseMethod:t('purchase'),seller:t('seller'),priceMin:'≥',priceMax:'≤'};return Object.entries(f).filter(([k,v])=>meta[k]&&v!==''&&v!=='ALL').map(([k,v])=>`<button class="filter-chip" data-clear-filter="${k}"><span>${meta[k]}</span>${esc(k.startsWith('price')?money(v):facetValueLabel(k,v))}<b>×</b></button>`).join('')}
function facetValueLabel(key,value){const map={category:'categories',era:'eras',country:'countries',material:'materials',technique:'techniques',condition:'conditions',location:'locations',purchaseMethod:'purchaseMethods',seller:'sellers'},item=state.catalog.facets[map[key]]?.find(x=>x.value===value);return item?l(item.label):value}
function shop(){const xs=filteredEntries();return`<section class="page section"><div class="section-head editorial-head"><div><div class="eyebrow">ANTIQUA · OBJECT NETWORK</div><h1>${t('shop')}</h1><p class="muted">${t('shopIntro')}</p></div><a class="secondary-button compare-head-button ${state.compare.length<2?'disabled':''}" href="#compare">${t('comparison')} · ${state.compare.length}</a></div>${purposeBar()}<div class="catalog-search-row"><input id="catalogSearch" value="${esc(state.filters.q)}" placeholder="${t('search')}" autocomplete="off"><button class="secondary-button mobile-facet-trigger" data-open-filters>${t('filters')} ${activeFilterCount()?`· ${activeFilterCount()}`:''}</button><select data-filter="sort" class="sort-select"><option value="RECOMMENDED">${t('recommended')}</option><option value="PRICE_ASC" ${state.filters.sort==='PRICE_ASC'?'selected':''}>${t('priceAsc')}</option><option value="PRICE_DESC" ${state.filters.sort==='PRICE_DESC'?'selected':''}>${t('priceDesc')}</option><option value="ENDING" ${state.filters.sort==='ENDING'?'selected':''}>${t('ending')}</option></select></div><div class="active-filters" id="activeFilters">${filterChips()}</div><div class="catalog-layout">${facetPanel()}<div class="catalog-results"><div class="catalog-result-head"><span id="catalogCount">${xs.length} ${t('results')}</span></div><div class="object-grid" id="catalogGrid">${xs.length?xs.map(card).join(''):`<div class="empty-state catalog-empty">${t('noResults')}</div>`}</div></div></div></section>${compareDock()}`}
function auctionsView(){const entries=state.catalog.auctions.map(a=>entryForLot(state.catalog.lots.find(o=>o.id===a.lotId))).filter(x=>x.lot);return`<section class="page section"><div class="section-head"><div><div class="eyebrow">AUCTION INTEGRITY ENGINE</div><h1>${t('auctions')}</h1><p class="muted">${t('auctionIntro')}</p></div><div class="foundation-pill">${esc(state.health.auctionIntegrity.engine)}</div></div><div class="object-grid">${entries.map(card).join('')}</div></section>${compareDock()}`}
function collectionsView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">${t('collectionGraph')}</div><h1>${t('collections')}</h1><p class="muted">${t('collectionIntro')}</p></div></div><div class="collection-grid">${state.collections.map(c=>{const cover=c.items?.find(x=>x.objectId===c.coverObjectId)?.object||c.items?.[0]?.object;return`<a class="collection-card" href="#collection/${esc(c.id)}"><div class="collection-cover">${cover?`<img loading="lazy" src="${esc(cover.image)}" alt="">`:''}</div><div class="collection-copy"><div class="micro">${status(c.collectionType)} · ${status(c.visibility)}</div><h2>${esc(l(c.title))}</h2><p>${esc(l(c.summary))}</p><strong>${c.items?.length||0} ${t('objects')}</strong></div></a>`}).join('')}</div><div class="section-head split-head"><div><div class="eyebrow">${t('virtualReunification')}</div><h2>${t('distributedEnsembles')}</h2></div></div><div class="ensemble-grid">${state.ensembles.map(e=>`<a class="ensemble-card" href="#ensemble/${esc(e.id)}"><div class="ensemble-orbit"><strong>${e.completeness?.knownPercent||0}%</strong><span>${t('known')}</span></div><div><div class="micro">${status(e.status)}</div><h2>${esc(l(e.title))}</h2><p>${esc(l(e.summary))}</p><div class="progress"><i style="width:${e.completeness?.verifiedPercent||0}%"></i></div><div class="ensemble-stats"><span>${t('verified')}: ${e.completeness?.verified||0}/${e.completeness?.total||0}</span><span>${t('missing')}: ${e.completeness?.missing||0}</span></div></div></a>`).join('')}</div></section>`}
function exhibitionsView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">CURATED DIGITAL SPACE</div><h1>${t('exhibitions')}</h1><p class="muted">${t('exhibitionIntro')}</p></div></div><div class="exhibition-grid">${state.exhibitions.map(e=>{const cover=state.catalog.lots.find(x=>x.id===e.coverObjectId);return`<a href="#exhibition/${esc(e.id)}" class="exhibition-card"><div class="exhibition-image">${cover?`<img loading="lazy" src="${esc(cover.image)}" alt="">`:''}<span>${status(e.status)}</span></div><div class="exhibition-copy"><div class="micro">${t('onlineExhibition')}</div><h2>${esc(l(e.title))}</h2><p>${esc(l(e.subtitle))}</p><div class="text-link">${t('open')} →</div></div></a>`}).join('')}</div></section>`}
function dealersView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">PROFESSIONAL TRADE</div><h1>${t('dealers')}</h1></div></div><div class="dealer-grid">${state.catalog.sellers.map(s=>`<a class="dealer-card dealer-link" href="#dealer/${esc(s.id)}"><div class="dealer-card-top"><div class="verified-line">${s.verified?'✓ '+t('verifiedDealer'):t('reviewPending')}</div><span class="dealer-place">${esc(l(s.city))}</span></div><h2>${esc(s.name)}</h2><p>${esc(l(s.about))}</p><div class="dealer-specialties">${(s.specialties||[]).slice(0,3).map(x=>`<span>${esc(l(x))}</span>`).join('')}</div><small>${s.since?`${t('since')} ${s.since}`:''}</small></a>`).join('')}</div></section>`}
async function dealerPage(id){const d=await api(`/api/sellers/${encodeURIComponent(id)}`),s=d.seller;return`<section class="dealer-profile"><div class="dealer-profile-hero"><div class="page"><a class="text-link" href="#dealers">← ${t('dealers')}</a><div class="dealer-profile-grid"><div><div class="eyebrow">${s.verified?'✓ '+t('verifiedDealer'):t('reviewPending')}</div><h1>${esc(s.name)}</h1><p class="lead">${esc(l(s.about))}</p><div class="dealer-meta"><span>${esc(l(s.city))}, ${esc(l(s.country))}</span>${s.since?`<span>${t('since')} ${s.since}</span>`:''}${s.responseHours?`<span>${t('response')} ${s.responseHours} ${t('hours')}</span>`:''}</div></div><aside class="dealer-trust-card"><strong>${s.verified?'✓':'…'}</strong><span>${s.verified?t('verifiedDealer'):t('reviewPending')}</span>${s.rating?`<b>${s.rating.toFixed(1)} / 5</b>`:''}</aside></div></div></div><div class="page section"><div class="block-head"><div><div class="eyebrow">${t('dealerStore')}</div><h2>${t('itemsAvailable')}</h2></div></div><div class="object-grid">${d.inventory.map(x=>card({lot:x.lot,listing:x,auction:null,seller:x.seller,method:x.saleType,price:x.price,currency:x.currency})).join('')}</div><div class="dealer-policy"><h2>${t('policies')}</h2><p>${esc(l(s.policies))}</p></div></div></section>${compareDock()}`}
function compareDock(){if(!state.compare.length)return'';return`<div class="compare-dock"><span>${t('comparison')}: <strong>${state.compare.length}/4</strong></span><div><button class="text-button" data-clear-compare>${t('clear')}</button><a class="primary-button" href="#compare">${t('compare')}</a></div></div>`}
function compareView(){const objects=state.compare.map(id=>state.catalog.lots.find(o=>o.id===id)).filter(Boolean);if(objects.length<2)return`<section class="page section"><div class="section-head"><div><div class="eyebrow">OBJECT STUDY</div><h1>${t('comparison')}</h1><p class="muted">${t('selectTwo')}</p></div></div></section>${compareDock()}`;const rows=[['maker',state.lang==='ru'?'Автор / мастерская':'Maker / workshop',o=>l(o.maker)],['period',t('era'),o=>l(o.period)],['origin',t('country'),o=>l(o.origin)],['materials',t('materials'),o=>l(o.materials)],['technique',t('techniqueLabel'),o=>l(o.technique)],['dimensions',t('dimensions'),o=>l(o.dimensions)],['condition',t('conditionGrade'),o=>l(o.conditionLabel)],['location',t('location'),o=>l(o.locationLabel)],['purchase',t('purchase'),o=>(o.purchaseMethods||[]).map(methodLabel).join(', ')],['price',t('price'),o=>{const e=entryForLot(o);return e.price!=null?money(e.price,e.currency):'—'}]];return`<section class="page section compare-page"><div class="section-head"><div><div class="eyebrow">OBJECT STUDY</div><h1>${t('comparison')}</h1><p class="muted">${t('compareIntro')}</p></div><button class="secondary-button" data-clear-compare>${t('clear')}</button></div><div class="compare-scroll"><div class="compare-grid" style="--compare-count:${objects.length}"><div class="compare-label"></div>${objects.map(o=>`<article class="compare-object"><button class="compare-remove" data-compare="${esc(o.id)}">×</button><button class="image-button" data-passport="${esc(o.id)}"><img src="${esc(o.image)}" alt=""></button><h2>${esc(l(o.title))}</h2><small>${esc(o.objectId)}</small></article>`).join('')}${rows.map(([,label,get])=>`<div class="compare-label">${esc(label)}</div>${objects.map(o=>`<div class="compare-cell">${esc(get(o))}</div>`).join('')}`).join('')}</div></div></section>${compareDock()}`}
function authView(){return`<section class="page section"><div class="auth-grid"><form id="login"><h2>${t('signIn')}</h2><label>Email<input name="email" type="email" autocomplete="email" required></label><label>${t('password')}<input name="password" type="password" autocomplete="current-password" required></label><button class="primary-button">${t('signIn')}</button></form><form id="register"><h2>${t('createAccount')}</h2><label>${t('name')}<input name="displayName" required></label><label>Email<input name="email" type="email" required></label><label>${t('password')}<input name="password" type="password" required></label><label>${t('accountType')}<select name="accountType"><option value="BUYER">${t('buyer')}</option><option value="SELLER">${t('sellerRole')}</option></select></label><button class="secondary-button">${t('createAccount')}</button></form></div></section>`}
const orderSteps=['ORDER_CREATED','AWAITING_PAYMENT_CONNECTOR','PAID','RELEASE_APPROVED','PACKING','SHIPPED','DELIVERED','OWNERSHIP_TRANSFERRED'];
function orderStepLabel(x){const m={ORDER_CREATED:t('orderCreated'),AWAITING_PAYMENT_CONNECTOR:t('awaitingPayment'),PAID:t('paid'),RELEASE_APPROVED:t('releaseApproved'),PACKING:t('packing'),SHIPPED:t('shipped'),DELIVERED:t('delivered'),OWNERSHIP_TRANSFERRED:t('ownershipTransferred')};return m[x]||status(x)}
function orderTimeline(o){let idx=orderSteps.indexOf(o.status);if(idx<0)idx=0;return`<div class="order-timeline">${orderSteps.map((s,i)=>`<div class="timeline-step ${i<=idx?'done':''}"><i></i><span>${orderStepLabel(s)}</span></div>`).join('')}</div>`}
function notificationView(n){
 const p=n.payload||{},o=state.catalog.lots.find(x=>x.id===p.objectId),name=l(o?.title)||p.objectId||'';
 if(n.type==='WATCH_LISTING_CHANGED'){
  const bits=[];if(p.priceChanged)bits.push((state.lang==='ru'?'Цена':'Price')+': '+money(p.previousPrice,p.currency)+' → '+money(p.price,p.currency));if(p.statusChanged)bits.push((state.lang==='ru'?'Статус':'Status')+': '+status(p.previousStatus)+' → '+status(p.status));
  return{title:state.lang==='ru'?'Изменение наблюдаемого предмета':'Watched object changed',body:(name?name+' · ':'')+bits.join(' · '),objectId:p.objectId}
 }
 if(n.type==='WATCH_AUCTION_ACTIVITY')return{title:state.lang==='ru'?'Активность по наблюдаемому аукциону':'Watched auction activity',body:(name?name+' · ':'')+(state.lang==='ru'?'Текущая ставка':'Current bid')+': '+money(p.currentBid,p.currency)+' · '+Number(p.bidCount||0)+' '+t('bids'),objectId:p.objectId};
 return{title:status(n.type),body:Object.entries(p).slice(0,2).map(([k,v])=>k+': '+v).join(' · '),objectId:p.objectId||null}
}
function activityFeed(){const ns=state.client?.notifications||[];return`<aside class="activity-panel"><div class="block-head"><div><div class="eyebrow">${t('notifications')}</div><h2>${t('activity')}</h2></div>${ns.some(n=>!n.readAt)?`<button class="text-button" data-read-all>${t('readAll')}</button>`:''}</div><div class="activity-feed">${ns.length?ns.map(n=>{const v=notificationView(n);return`<article class="activity-item ${n.readAt?'':'unread'}"><i class="activity-mark"></i><div><strong>${esc(v.title)}</strong><p>${esc(v.body)}</p>${v.objectId?`<button class="text-button" data-passport="${esc(v.objectId)}">${t('open')}</button>`:''}</div><time>${relative(n.createdAt)}</time></article>`}).join(''):`<div class="empty-state">${t('noActivity')}</div>`}</div></aside>`}
function accountView(){if(!state.me.account)return authView();const a=state.me.account,c=state.client,v=c.verification,isSeller=Boolean(c.seller),saved=(c.savedLots||[]).map(id=>state.catalog.lots.find(o=>o.id===id)).filter(Boolean);return`<section class="page section account-v12"><div class="account-hero"><div><div class="eyebrow">${isSeller?t('sellerRole'):t('buyer')}</div><h1>${esc(a.displayName)}</h1><p>${esc(a.email)}</p></div><div class="account-identity"><span>${esc(a.roles.map(status).join(' · '))}</span><b>${t('verification')}: ${status(v?.status||'NOT_STARTED')}</b></div></div><div class="v12-kpis"><div class="kpi"><strong>${saved.length}</strong><span>${t('saved')}</span></div><div class="kpi"><strong>${c.leadingLots?.length||0}</strong><span>${t('bids')}</span></div><div class="kpi"><strong>${c.offers?.length||0}</strong><span>${t('offers')}</span></div><div class="kpi"><strong>${c.orders?.length||0}</strong><span>${t('orders')}</span></div></div><div class="account-layout"><div>${isSeller?sellerWorkspace(c):buyerWorkspace(c,saved)}<section class="account-security"><div class="block-head"><div><div class="eyebrow">ACCOUNT PROTECTION</div><h2>${t('security')}</h2></div></div><div class="security-grid"><div><span>${t('roles')}</span><strong>${esc(a.roles.join(', '))}</strong></div><div><span>2FA</span><strong>${status(a.twofaStatus)}</strong></div><div><span>${esc(v?.caseType||'KYC')}</span><strong>${status(v?.status||'NOT_STARTED')}</strong></div><div><span>${t('persistence')}</span><strong>${esc(state.health.persistence.kind)}</strong></div></div>${a.twofaStatus==='DISABLED'?`<button class="secondary-button" data-setup-2fa>${t('setup2fa')}</button>`:''}</section></div>${activityFeed()}</div></section>`}
function buyerWorkspace(c,saved){const watched=(c.watchAlerts||[]).map(id=>state.catalog.lots.find(o=>o.id===id)).filter(Boolean);return`<section class="account-block"><div class="block-head"><div><div class="eyebrow">COLLECTOR WORKSPACE</div><h2>${t('saved')}</h2></div></div>${saved.length?`<div class="account-card-grid compact">${saved.map(o=>`<article class="account-card"><button class="image-button mini-object" data-passport="${esc(o.id)}"><img src="${esc(o.image)}" alt=""></button><h3>${esc(l(o.title))}</h3><button class="quiet-button" data-passport="${esc(o.id)}">${t('open')}</button></article>`).join('')}</div>`:`<div class="empty-state">${t('noResults')}</div>`}</section><section id="watchlistV19" class="account-block"><div class="block-head"><div><div class="eyebrow">WATCHLIST</div><h2>${state.lang==='ru'?'Наблюдаю':'Watching'}</h2><p>${state.lang==='ru'?'Уведомления об изменении цены, доступности и аукционной активности.':'Notifications for price, availability and auction activity.'}</p></div></div>${watched.length?`<div class="account-card-grid compact">${watched.map(o=>`<article class="account-card"><button class="image-button mini-object" data-passport="${esc(o.id)}"><img src="${esc(o.image)}" alt=""></button><h3>${esc(l(o.title))}</h3><div class="seller-listing-actions"><button class="quiet-button" data-passport="${esc(o.id)}">${t('open')}</button><button class="text-button" data-watch="${esc(o.id)}">${state.lang==='ru'?'Не следить':'Stop watching'}</button></div></article>`).join('')}</div>`:`<div class="empty-state">${state.lang==='ru'?'Вы пока не наблюдаете ни за одним предметом':'You are not watching any objects yet'}</div>`}</section><section class="account-block"><div class="block-head"><div><div class="eyebrow">NEGOTIATION</div><h2>${t('offers')}</h2></div></div>${c.offers?.length?`<div class="account-card-grid">${c.offers.map(o=>`<article class="account-card"><div class="account-card-head"><strong>${money(o.buyerAmount||o.sellerAmount,o.currency)}</strong><span class="status-pill">${status(o.status)}</span></div><h3>${esc(l(state.catalog.lots.find(x=>x.id===o.lotId)?.title)||o.lotId)}</h3></article>`).join('')}</div>`:`<div class="empty-state">${t('noOffers')}</div>`}</section><section class="account-block"><div class="block-head"><div><div class="eyebrow">POST-SALE</div><h2>${t('orders')}</h2></div></div>${c.orders?.length?`<div class="account-card-grid">${c.orders.map(orderCard).join('')}</div>`:`<div class="empty-state">${t('noOrders')}</div>`}</section>`}
function bilingualField(name,label,d={},kind='input',cls=''){
 const en=d?.[name]?.en||'',ru=d?.[name]?.ru||'',tag=kind==='textarea'?'textarea':'input';
 return`<label class="${cls}">${label} (RU)<${tag} name="${name}Ru" ${kind==='textarea'?'rows="3"':''} value="${kind==='textarea'?'':esc(ru)}" required>${kind==='textarea'?esc(ru):''}</${tag}></label><label class="${cls}">${label} (EN)<${tag} name="${name}En" ${kind==='textarea'?'rows="3"':''} value="${kind==='textarea'?'':esc(en)}" required>${kind==='textarea'?esc(en):''}</${tag}></label>`
}
function draftFormFields(d={}){
 const route=d.saleRoute||'SHOP';
 return`${bilingualField('title',state.lang==='ru'?'Название':'Title',d)}${bilingualField('category',state.lang==='ru'?'Категория':'Category',d)}${bilingualField('maker',state.lang==='ru'?'Автор / мастер':'Maker',d)}${bilingualField('period',state.lang==='ru'?'Период':'Period',d)}${bilingualField('origin',state.lang==='ru'?'Происхождение':'Origin',d)}${bilingualField('materials',state.lang==='ru'?'Материалы':'Materials',d)}${bilingualField('dimensions',state.lang==='ru'?'Размеры':'Dimensions',d)}${bilingualField('description',state.lang==='ru'?'Описание':'Description',d,'textarea')}${bilingualField('provenance','Provenance',d,'textarea')}${bilingualField('condition',state.lang==='ru'?'Состояние':'Condition',d,'textarea')}<label>${state.lang==='ru'?'Маршрут продажи':'Sale route'}<select name="saleRoute"><option value="SHOP" ${route==='SHOP'?'selected':''}>SHOP · ${state.lang==='ru'?'прямая продажа':'direct sale'}</option><option value="AUCTION" ${route==='AUCTION'?'selected':''}>AUCTION · ${state.lang==='ru'?'аукцион':'auction'}</option><option value="PRIVATE" ${route==='PRIVATE'?'selected':''}>PRIVATE · ${state.lang==='ru'?'частная продажа':'private sale'}</option></select></label><label>${state.lang==='ru'?'Цена прямой продажи':'Direct sale price'}<input name="price" type="number" min="0" step="1" value="${esc(d.price||'')}"></label><label>${state.lang==='ru'?'Нижняя оценка / старт':'Low estimate / start'}<input name="estimateLow" type="number" min="0" step="1" value="${esc(d.estimateLow||'')}"></label><label>${state.lang==='ru'?'Верхняя оценка':'High estimate'}<input name="estimateHigh" type="number" min="0" step="1" value="${esc(d.estimateHigh||'')}"></label><label class="span-2">${state.lang==='ru'?'Откуда отправляется':'Ships from'}<input name="shippingFrom" value="${esc(d.shippingFrom||'')}" required></label>`
}
function draftPatchFromForm(form){
 const d=Object.fromEntries(new FormData(form).entries()),out={saleRoute:d.saleRoute,price:Number(d.price||0),estimateLow:Number(d.estimateLow||0),estimateHigh:Number(d.estimateHigh||0),shippingFrom:String(d.shippingFrom||'')};
 for(const k of ['title','category','maker','period','origin','materials','dimensions','description','provenance','condition'])out[k]={en:String(d[k+'En']||''),ru:String(d[k+'Ru']||'')};
 return out
}
function sellerWorkspace(c){
 const s=c.seller,sellerId=c.sellerId||s.profile?.id,sellerAuctions=state.catalog.auctions.map(a=>({auction:a,lot:state.catalog.lots.find(o=>o.id===a.lotId)})).filter(x=>x.lot?.sellerId===sellerId);
 return`<section class="account-block"><div class="block-head"><div><div class="eyebrow">DEALER WORKSPACE</div><h2>${state.lang==='ru'?'Мои предметы и продажи':'My objects & sales'}</h2></div></div>
 <details class="seller-workspace-form"><summary><span>${state.lang==='ru'?'+ Новый предмет':' + New object'}</span><small>${state.lang==='ru'?'Создать карточку → media → проверка → публикация':'Create card → media → review → publish'}</small></summary><form id="sellerDraftCreateForm" class="seller-draft-form">${draftFormFields({})}<div class="span-2"><button class="primary-button" type="submit">${state.lang==='ru'?'Создать черновик':'Create draft'}</button></div></form></details>
 <div class="account-card-grid compact">${s.listings.length?s.listings.map(x=>`<article class="account-card ${x.status==='INACTIVE'?'listing-state-inactive':''}"><div class="account-card-head"><span class="status-pill">${status(x.status)}</span><strong>${money(x.price,x.currency)}</strong></div><h3>${esc(l(x.lot?.title)||x.lotId)}</h3><small>${methodLabel(x.saleType)} · ${x.negotiable?(state.lang==='ru'?'торг возможен':'negotiable'):(state.lang==='ru'?'фиксированная цена':'fixed price')}</small><div class="seller-listing-actions"><button class="quiet-button" data-passport="${esc(x.lotId)}">${t('open')}</button>${['ACTIVE','INACTIVE'].includes(x.status)?`<button class="secondary-button" data-manage-listing="${esc(x.id)}">${state.lang==='ru'?'Управлять':'Manage'}</button>`:''}</div></article>`).join(''):`<div class="empty-state">${state.lang==='ru'?'Опубликованных предметов пока нет':'No published objects yet'}</div>`}</div>
 ${sellerAuctions.length?`<div class="block-head compact-head"><div><div class="eyebrow">AUCTIONS</div><h3>${state.lang==='ru'?'Мои аукционы':'My auctions'}</h3></div></div><div class="account-card-grid compact">${sellerAuctions.map(({auction:a,lot:o})=>{const next=Number(a.currentBid)+Number(a.increment);return`<article class="account-card"><div class="account-card-head"><span class="status-pill">${status(a.state)}</span><strong>${money(a.currentBid,a.currency)}</strong></div><h3>${esc(l(o.title))}</h3><small>${state.lang==='ru'?'Следующая ставка':'Next bid'}: ${money(next,a.currency)} · ${state.lang==='ru'?'шаг':'step'} ${money(a.increment,a.currency)}</small><div class="draft-media-line">⏱ <span data-auction-timer data-ends-at="${esc(a.endsAt)}">${countdownText(a.endsAt)}</span> · ${a.bidCount} ${t('bids')}</div><button class="quiet-button" data-passport="${esc(o.id)}">${t('open')}</button></article>`}).join('')}</div>`:''}
 </section><section class="account-block"><div class="block-head"><div><div class="eyebrow">PUBLICATION PIPELINE</div><h2>${t('drafts')}</h2></div></div><div class="account-card-grid">${s.drafts.length?s.drafts.map(d=>{const editable=!['CATALOGUE_REVIEW','APPROVED','PUBLISHED'].includes(d.status),missing=(d.checklist?.checks||[]).filter(x=>!x.complete).map(x=>x.key).join(' · ');return`<article class="account-card draft-card"><div class="account-card-head"><span class="status-pill">${status(d.status)}</span><strong>${d.checklist.percent}%</strong></div><h3>${esc(l(d.title)||(state.lang==='ru'?'Без названия':'Untitled'))}</h3><div class="progress"><i style="width:${d.checklist.percent}%"></i></div><div class="draft-readiness"><small>${missing|| (state.lang==='ru'?'Готово к проверке':'Ready for review')}</small><b>${d.media?.length||0}/3 media</b></div><div class="seller-listing-actions">${editable?`<button class="quiet-button" data-edit-draft="${esc(d.id)}">${state.lang==='ru'?'Редактировать':'Edit'}</button><button class="quiet-button" data-draft-media="${esc(d.id)}">Media</button>`:''}${d.checklist.ready&&editable?`<button class="primary-button" data-submit-draft="${esc(d.id)}">${t('submitReview')}</button>`:''}</div></article>`}).join(''):`<div class="empty-state">${state.lang==='ru'?'Черновиков пока нет':'No drafts yet'}</div>`}</div></section><section class="account-block"><div class="block-head"><div><div class="eyebrow">COMMERCIAL</div><h2>${t('offers')} · ${t('orders')}</h2></div></div><div class="account-card-grid">${[...(c.offers||[]).map(o=>`<article class="account-card"><span class="status-pill">${status(o.status)}</span><h3>${esc(l(state.catalog.lots.find(x=>x.id===o.lotId)?.title)||o.lotId)}</h3><strong>${money(o.buyerAmount||o.sellerAmount,o.currency)}</strong></article>`),...(c.orders||[]).map(orderCard)].join('')||`<div class="empty-state">${t('noActivity')}</div>`}</div></section>`
}
