async function sha256File(file){const b=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function draftMediaSheet(id){
 const d=state.client?.seller?.drafts?.find(x=>x.id===id);if(!d)return;const configured=Boolean(state.health?.objectStorage?.configured),remaining=Math.max(0,12-(d.media?.length||0));
 openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">PRIVATE OBJECT STORAGE</div><h2>${state.lang==='ru'?'Медиа предмета':'Object media'}</h2><p>${d.media?.length||0}/3 ${state.lang==='ru'?'для checklist · до 12 файлов':'for checklist · up to 12 files'}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div>${configured?`<div class="action-sheet-field"><label>${state.lang==='ru'?'Фото / PDF':'Images / PDF'}<input id="draftMediaFiles" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" ${remaining?'':'disabled'}></label></div><p class="muted">${state.lang==='ru'?'Файл загружается напрямую в private storage и затем проверяется сервером по размеру, MIME и SHA-256.':'The file uploads directly to private storage and is then verified by size, MIME and SHA-256.'}</p><button class="primary-button" id="uploadDraftMedia" ${remaining?'':'disabled'}>${state.lang==='ru'?'Загрузить':'Upload'}</button>`:`<div class="empty-state">${state.lang==='ru'?'Object Storage не настроен в этой среде. Карточку можно заполнять, но загрузка файлов закрыта fail-closed.':'Object Storage is not configured in this environment. The card remains editable, but file upload is fail-closed.'}</div>`}</div>`);
 if(!configured)return;$('#uploadDraftMedia').onclick=async()=>{const files=[...($('#draftMediaFiles')?.files||[])].slice(0,remaining);if(!files.length)return toast(state.lang==='ru'?'Выберите файлы':'Choose files');const button=$('#uploadDraftMedia');button.disabled=true;try{let offset=d.media?.length||0;for(const file of files){const hash=await sha256File(file),role=file.type==='application/pdf'?'PROVENANCE_DOC':offset===0?'HERO':'DETAIL',intent=await api('/api/media/upload-intent',{method:'POST',body:JSON.stringify({draftId:id,contentType:file.type,bytes:file.size,sha256:hash,role})}),put=await fetch(intent.uploadUrl,{method:'PUT',headers:{'content-type':file.type},body:file});if(!put.ok)throw new Error(`Upload failed: ${put.status}`);await api(`/api/media/${intent.asset.id}/complete`,{method:'POST',body:'{}'});offset++}closeSheet();await refresh();await render();toast(state.lang==='ru'?'Медиа загружены и проверены':'Media uploaded and verified')}catch(err){button.disabled=false;toast(err.message)}} 
}
