function ensureMediaViewer(){if($('#mediaViewer'))return;const d=document.createElement('dialog');d.id='mediaViewer';d.className='media-viewer';d.innerHTML='<button class="media-viewer-close" data-close-media>×</button><button class="media-viewer-nav prev" data-media-nav="-1">‹</button><div class="media-stage"><img alt=""></div><button class="media-viewer-nav next" data-media-nav="1">›</button><div class="media-viewer-meta"></div>';document.body.appendChild(d);installMediaGestures(d)}
const mediaState={items:[],index:0,scale:1,x:0,y:0,pointers:new Map(),distance:0};
function openMedia(index=0){ensureMediaViewer();const dlg=$('#mediaViewer'),source=$('#dialog');try{mediaState.items=JSON.parse(source.dataset.gallery||'[]')}catch{mediaState.items=[]}if(!mediaState.items.length)return;mediaState.index=Math.max(0,Math.min(mediaState.items.length-1,index));mediaState.scale=1;mediaState.x=0;mediaState.y=0;renderMedia();dlg.showModal()}
