function mediaNav(delta){mediaState.index=(mediaState.index+delta+mediaState.items.length)%mediaState.items.length;mediaState.scale=1;mediaState.x=0;mediaState.y=0;renderMedia()}
function installMediaGestures(dlg){const stage=$('.media-stage',dlg),img=$('img',stage);const distance=()=>{const p=[...mediaState.pointers.values()];return p.length<2?0:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)};stage.addEventListener('pointerdown',e=>{mediaState.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY});stage.setPointerCapture?.(e.pointerId);if(mediaState.pointers.size===2)mediaState.distance=distance()});stage.addEventListener('pointermove',e=>{const p=mediaState.pointers.get(e.pointerId);if(!p)return;const oldX=p.x,oldY=p.y;p.x=e.clientX;p.y=e.clientY;if(mediaState.pointers.size===2){const d=distance();if(mediaState.distance){mediaState.scale=Math.max(1,Math.min(4,mediaState.scale*d/mediaState.distance));mediaState.distance=d}}else if(mediaState.scale>1){mediaState.x+=p.x-oldX;mediaState.y+=p.y-oldY}renderMedia()});const up=e=>{mediaState.pointers.delete(e.pointerId);mediaState.distance=distance()};stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',up);img.addEventListener('dblclick',()=>{mediaState.scale=mediaState.scale>1?1:2;mediaState.x=0;mediaState.y=0;renderMedia()})}
