  '<p class="v22-offer-authority-note">'+(state.lang==='ru'?'Предложение будет версионироваться; повторная отправка после сетевого сбоя не создаст дубль.':'The offer is versioned; retrying after a network failure will not create a duplicate.')+'</p>'+
  '<div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>'+t('close')+'</button><button class="primary-button" id="confirmOffer">'+t('sendOffer')+'</button></div></div>';
