async function collect(id){
 const mine=await api('/api/collections/mine'),collections=mine.collections||[];
 if(!collections.length){
  const d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">CURATED COLLECTIONS</div><h2>${state.lang==='ru'?'Сначала создайте коллекцию':'Create a collection first'}</h2><p>${state.lang==='ru'?'«Коллекция» — это отдельная кураторская подборка. Оценка, хранение и страхование ведутся отдельно в «Учёте предметов».':'A Collection is a separate curated grouping. Appraisal, storage and insurance remain in Collection Records.'}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>${t('close')}</button><button class="primary-button" id="openCuratedCollections">${state.lang==='ru'?'Перейти в мои коллекции':'Open my collections'}</button></div></div>`);
  $('#openCuratedCollections',d).onclick=()=>{closeSheet();closePassportForNavigation();localStorage.setItem('antiqua_v14_tab','collections');location.hash='account'};
  return
 }
 const options=collections.map(c=>`<option value="${esc(c.id)}">${esc(l(c.title)||c.id)} · ${status(c.visibility)}</option>`).join(''),d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">CURATED COLLECTIONS</div><h2>${t('addCollection')}</h2><p>${state.lang==='ru'?'Предмет будет добавлен в выбранную подборку. Личный учёт владения и хранения не изменится.':'The object will be added to the selected curated Collection. Your private ownership/storage record will not change.'}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-field"><label>${state.lang==='ru'?'Коллекция':'Collection'}<select id="curatedCollectionId">${options}</select></label></div><div class="action-sheet-field"><label>${state.lang==='ru'?'Раздел / тема':'Section / theme'}<input id="curatedCollectionSection" placeholder="${state.lang==='ru'?'Например: Серебро':'e.g. Silver'}"></label></div><div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>${t('close')}</button><button class="primary-button" id="confirmCollectionAdd">${t('addCollection')}</button></div></div>`);
 $('#confirmCollectionAdd',d).onclick=async()=>{const b=$('#confirmCollectionAdd',d),collectionId=$('#curatedCollectionId',d).value;b.disabled=true;try{await api(`/api/collections/${encodeURIComponent(collectionId)}/objects`,{method:'POST',body:JSON.stringify({objectId:id,section:$('#curatedCollectionSection',d).value.trim(),ownerDisplayMode:'ANONYMOUS',locationDisplayMode:'HIDDEN'})});closeSheet();toast(t('addedCollection'))}catch(e){b.disabled=false;toast(e.message)}}
}
function installPressPhysics(){document.addEventListener('pointerdown',e=>{const b=e.target.closest('button,a.primary-button,a.secondary-button');if(b)b.classList.add('is-pressed');const c=e.target.closest('[data-direct-card]');if(c&&!e.target.closest('button,a,input,select,textarea')){c.classList.add('is-pressing');c._press={id:e.pointerId,x:e.clientX,y:e.clientY}}},{capture:true});document.addEventListener('pointermove',e=>{const c=e.target.closest?.('[data-direct-card]')||$('.is-pressing');if(!c?._press||c._press.id!==e.pointerId)return;c.style.setProperty('--press-x',`${Math.max(-7,Math.min(7,(e.clientX-c._press.x)*.15))}px`);c.style.setProperty('--press-y',`${Math.max(-7,Math.min(7,(e.clientY-c._press.y)*.12))}px`)},{capture:true});const up=e=>{$$('.is-pressed').forEach(x=>x.classList.remove('is-pressed'));$$('.is-pressing').forEach(c=>{c.classList.remove('is-pressing');c.style.setProperty('--press-x','0px');c.style.setProperty('--press-y','0px');delete c._press})};document.addEventListener('pointerup',up,{capture:true});document.addEventListener('pointercancel',up,{capture:true})}
function installDossierSwipe(){let s=null;const dlg=$('#dialog');dlg.addEventListener('pointerdown',e=>{if(innerWidth>800||e.target.closest('button,a,input,select,textarea,.dossier-commerce-dock'))return;s={id:e.pointerId,x:e.clientX,y:e.clientY}});dlg.addEventListener('pointerup',e=>{if(!s||s.id!==e.pointerId)return;const dx=e.clientX-s.x,dy=e.clientY-s.y;s=null;if(Math.abs(dx)>85&&Math.abs(dx)>Math.abs(dy)*1.5)nextPassport(dx<0?1:-1)})}
function cyclePersona(){if(!state.health.preview){location.hash='account';return}const r=state.me.account?.roles||[],next=r.includes('ADMIN')?'BUYER':r.includes('SELLER')?'OPERATOR':'SELLER';state.persona=next;localStorage.setItem('antiqua_persona',next);api('/api/auth/demo-login',{method:'POST',body:JSON.stringify({persona:next})}).then(refresh).then(()=>{location.hash=next==='OPERATOR'?'trust':'account';return render()}).catch(e=>toast(e.message))}
document.addEventListener('click',async e=>{try{const direct=e.target.closest('[data-open-passport]'),interactive=e.target.closest('button,a,input,select,textarea,label');if(direct&&!interactive){e.preventDefault();return passport(direct.dataset.openPassport)}const target=e.target.closest('button,a');if(!target)return;if(target.dataset.purposeFilter){state.filters.purpose=target.dataset.purposeFilter;state.filters.purchaseMethod='ALL';return render()}if(target.matches('[data-close-dialog]'))return closePassportFromUi();if(target.matches('[data-close-before-nav]'))return closePassportForNavigation();if(target.matches('[data-close-sheet]'))return closeSheet();if(target.matches('[data-close-media]'))return $('#mediaViewer')?.close();if(target.dataset.mediaNav)return mediaNav(Number(target.dataset.mediaNav));if(target.dataset.lang){state.lang=target.dataset.lang;localStorage.setItem('antiqua_lang',state.lang);syncShell();return render()}if(target.id==='persona')return cyclePersona();if(target.dataset.passport){e.preventDefault();return passport(target.dataset.passport)}if(target.dataset.shareObject){e.preventDefault();return copyPassportLink(target.dataset.shareObject)}if(target.dataset.thumb!=null){const i=Number(target.dataset.thumb),dlg=$('#dialog'),gallery=JSON.parse(dlg.dataset.gallery||'[]');$('.dossier-hero img',dlg).src=gallery[i];$$('[data-thumb]',dlg).forEach(x=>x.classList.toggle('active',x===target));$('.dossier-hero',dlg).dataset.mediaIndex=String(i);return}if(target.dataset.mediaIndex!=null)return openMedia(Number(target.dataset.mediaIndex));if(target.dataset.neighbor)return nextPassport(Number(target.dataset.neighbor));if(target.dataset.compare)return toggleCompare(target.dataset.compare);if(target.matches('[data-clear-compare]')){state.compare=[];persistCompare();return render()}if(target.dataset.save)return toggleSave(target.dataset.save);if(target.dataset.watch)return toggleWatch(target.dataset.watch);if(target.dataset.collect)return collect(target.dataset.collect);if(target.dataset.buy)return buyNow(target.dataset.buy);if(target.dataset.offer)return offerSheet(target);if(target.dataset.bid)return bidSheet(target);if(target.matches('[data-open-filters]'))return filterSheet();if(target.matches('[data-reset-filters]')){resetFilters();return render()}if(target.dataset.clearFilter){state.filters[target.dataset.clearFilter]=target.dataset.clearFilter.startsWith('price')?'':'ALL';return render()}if(target.matches('[data-read-all]')){await api('/api/notifications/read-all',{method:'POST',body:'{}'});await refresh();return render()}if(target.matches('[data-setup-2fa]'))return twoFactorSheet();if(target.dataset.order)return orderSheet(target.dataset.order);if(target.dataset.editDraft)return draftEditorSheet(target.dataset.editDraft);if(target.dataset.draftMedia)return draftMediaSheet(target.dataset.draftMedia);if(target.dataset.manageListing)return listingEditorSheet(target.dataset.manageListing);if(target.dataset.submitDraft){await api(`/api/seller/drafts/${target.dataset.submitDraft}/submit`,{method:'POST',body:'{}'});await refresh();return render()}if(target.dataset.claim)return claimSheet(target);if(target.dataset.op)return operatorAction(target)}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{const card=e.target.closest?.('[data-open-passport]');if(!card||e.target!==card||!['Enter',' '].includes(e.key))return;e.preventDefault();passport(card.dataset.openPassport).catch(err=>toast(err.message))});
